function sharedService(n,t){function i(n){let i="Config/EmailConfig/",r=JSON.stringify({tipo:2,...n});return showLoader(),t.getData("get",`${i}Get?json=${r}`).then(n=>{let t={correos:[],telefonos:[],telefonoEstab:null};if(n.code==="1"){let[u]=JSON.parse(n.payload),{correo:i,telefono:r,telefonoEstab:f,correoEstab:e,nombreEstab:o}=u[0];t.correos=i?i.split(/[\|;]/):[];t.telefonos=r?r.split(/[\|;]/):[];t.telefonoEstab=f;t.correoEstab=e;t.nombreEstab=o}return t}).finally(()=>hideLoader())}return{getDataFormNotificacion:i}}app.factory("sharedService",sharedService);sharedService.$inject=["$injector","mainService"];